// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint128).max);

        vm.deal(caller, amount);
        vm.startPrank(caller);
        (bool fallbackOk, ) = address(c).call{value: amount}("");
        require(fallbackOk, "fallback deposit failed");

        uint256 preCallerEth = caller.balance;
        bool success;
        try c.withdraw() { success = true; } catch { success = false; }
        vm.stopPrank();

        assertTrue(!success || (c.balances(caller) == 0 && caller.balance == preCallerEth + amount));
    }
}
